# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from collections import Counter
from typing import List, Tuple

from hourglass.errors import ProjectError
from hourglass.models import Shift
from hourglass.schedule import worker_minutes

Row = Tuple[str, int, int]


def validate_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")


def busyness(entry: Row) -> tuple:
    return (-entry[2], entry[0])


def summarize(shifts: List[Shift]) -> List[Row]:
    totals = worker_minutes(shifts)
    counts = Counter(item.worker for item in shifts)
    rows = [
        (name, counts[name], mins)
        for name, mins in totals.items()
    ]
    return sorted(rows, key=busyness)


def format_row(entry: Row) -> str:
    name, count, mins = entry
    return f"{name}: {count} shifts, {mins / 60:.1f} hours"


def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first."""
    validate_shifts(shifts)
    return [format_row(row) for row in summarize(shifts)]

